<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class StudentDisciplineController extends Controller{
 private function staff(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->hasRole('upbringing_head')||$r->user()->hasRole('curator')||$r->user()->hasRole('teacher'),403);}
 public function index(Request $r){$this->staff($r);$p=$r->attributes->get('academic_period');$rows=DB::table('student_behavior_incidents as i')->join('students as s','s.id','=','i.student_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('lesson_occurrences as l','l.id','=','i.lesson_occurrence_id')->leftJoin('subjects as sub','sub.id','=','l.subject_id')->where('i.academic_period_id',$p->id)->select('i.*','s.last_name','s.first_name','s.middle_name','g.name as group_name','sub.name as subject_name','l.lesson_date')->orderByRaw("case i.status when 'new' then 0 when 'in_work' then 1 else 2 end")->orderByDesc('i.created_at')->get();return view('upbringing.discipline',compact('rows'));}
 public function store(Request $r){$this->staff($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['student_id'=>'required|exists:students,id','lesson_occurrence_id'=>'nullable|exists:lesson_occurrences,id','type'=>'required|in:disruption,aggression,conflict,bullying,smoking,property,phone,insubordination,other','severity'=>'required|in:normal,high,critical','description'=>'required|string|max:5000','action_taken'=>'nullable|string|max:5000']);DB::table('student_behavior_incidents')->insert($d+['academic_period_id'=>$p->id,'status'=>'new','reported_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Инцидент зарегистрирован.');}
 public function resolve(Request $r,$id){$this->staff($r);$x=DB::table('student_behavior_incidents')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['status'=>'required|in:in_work,resolved','action_taken'=>'nullable|string|max:5000']);DB::table('student_behavior_incidents')->where('id',$id)->update($d+['resolved_by'=>$d['status']==='resolved'?$r->user()->id:null,'resolved_at'=>$d['status']==='resolved'?now():null,'updated_at'=>now()]);return back();}
}